name: PR Preview Deployment

on:
  pull_request:
    paths:
      - 'website/**'
  workflow_dispatch:

jobs:
  build-and-deploy:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout Code
        uses: actions/checkout@v4

      - name: Setup .NET
        uses: actions/setup-dotnet@v4
        with:
          dotnet-version: '6.0.x'

      - name: Restore Dependencies
        run: |
          cd website
          dotnet restore

      - name: Build Website
        run: |
          cd website
          dotnet publish -c Release -o ./publish

      - name: Upload Artifact
        uses: actions/upload-pages-artifact@v3
        with:
          path: website/publish
          retention-days: 30

      - name: Deploy to Cloudflare Pages
        if: ${{ github.event_name == 'pull_request' && env.CLOUDFLARE_API_TOKEN && env.CLOUDFLARE_ACCOUNT_ID }}
        uses: cloudflare/pages-action@v1
        with:
          apiToken: ${{ secrets.CLOUDFLARE_API_TOKEN }}
          accountId: ${{ secrets.CLOUDFLARE_ACCOUNT_ID }}
          projectName: razorconsole
          directory: website/publish
          gitHubToken: ${{ secrets.GITHUB_TOKEN }}

      - name: Post PR Comment
        if: ${{ github.event_name == 'pull_request' }}
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const fs = require('fs');
            const { execSync } = require('child_process');

            // Get PR number
            const prNumber = context.issue.number;

            // Get artifact URL
            const artifactUrl = `https://github.com/${context.repo.owner}/${context.repo.repo}/actions/runs/${context.runId}/artifacts`;

            // Check if Cloudflare deployment was successful
            let cloudflareLink = '';
            if (process.env.CLOUDFLARE_PAGES_URL) {
              cloudflareLink = `\n\n[Live Preview](${process.env.CLOUDFLARE_PAGES_URL})`;
            }

            // Prepare comment content
            const commentBody = `## 🚀 PR Preview Deployment

This PR has been deployed for preview:
- **Artifact**: [Download here](${artifactUrl})
${cloudflareLink}

> ⚠️ This preview will be automatically deleted after 30 days.
> 🔧 For advanced deployment options, see [Preview Deployment Guide](https://github.com/${context.repo.owner}/${context.repo.repo}/blob/main/.github/PREVIEW_DEPLOYMENT.md)`;

            // Find existing comment from this action
            const { data: comments } = await github.rest.issues.listComments({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: prNumber
            });

            const existingComment = comments.find(comment => 
              comment.body.includes('PR Preview Deployment')
            );

            if (existingComment) {
              // Update existing comment
              await github.rest.issues.updateComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                comment_id: existingComment.id,
                body: commentBody
              });
            } else {
              // Create new comment
              await github.rest.issues.createComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: prNumber,
                body: commentBody
              });
            }
